package com.apexstreet.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="automation_event_plans") public class AutomationEventPlan { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="area_id",nullable=false) private Area area; @Column(nullable=false,length=150) private String name; @Column(name="event_date",nullable=false) private LocalDate eventDate; @Column(nullable=false) private Integer brightness; @Column(nullable=false) private boolean enabled=true; @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt; @PrePersist void c(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;} @PreUpdate void u(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public Area getArea(){return area;} public void setArea(Area v){area=v;} public String getName(){return name;} public void setName(String v){name=v;} public LocalDate getEventDate(){return eventDate;} public void setEventDate(LocalDate v){eventDate=v;} public Integer getBrightness(){return brightness;} public void setBrightness(Integer v){brightness=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} }
